import fs from 'node:fs';
import { PRODUCT_TERM_SCHEMAS, PRODUCT_TERMS_VERSION } from '../../lib/finance/product-terms.mjs';
const schema = JSON.stringify(PRODUCT_TERM_SCHEMAS);
const sql = `-- Generated by scripts/platform-intelligence/generate-product-terms-sql.mjs.
-- Canonical metadata: lib/finance/product-terms.mjs. Do not edit this SQL by hand.
begin;
insert into public.fin_settings(key,value) select 'product_terms_previous_marker',value from public.fin_settings where key='schema_version' on conflict(key) do nothing;
create or replace function public.fin_valid_product_terms(p_category text,p_terms jsonb)
returns boolean language plpgsql immutable security invoker set search_path='' as $body$
declare catalog jsonb := $schema$${schema}$schema$::jsonb; s jsonb; f jsonb; v jsonb; k text; vals jsonb; d date;
begin
 if jsonb_typeof(p_terms) is distinct from 'object' or length(p_terms::text)>16000 or p_terms->>'schema_version' is distinct from '${PRODUCT_TERMS_VERSION}' or p_terms::text ~ '[<>]' then return false; end if;
 if exists(select 1 from jsonb_object_keys(p_terms) x where x not in ('schema_version','modality','values')) then return false; end if;
 s:=catalog->(p_terms->>'modality');
 if s is null or s->>'category' is distinct from p_category or jsonb_typeof(p_terms->'values') is distinct from 'object' then return false; end if;
 vals:=p_terms->'values';
 for k in select jsonb_object_keys(vals) loop
  if not exists(select 1 from jsonb_array_elements(s->'fields') x where x->>'key'=k) then return false; end if;
 end loop;
 for f in select * from jsonb_array_elements(s->'fields') loop
  k:=f->>'key'; v:=vals->k;
  if v is null then if (f->>'required')::boolean then return false; else continue; end if; end if;
  if f->>'type'='number' then
   if jsonb_typeof(v) is distinct from 'number' then return false; end if;
   if (v#>>'{}')::numeric<>round((v#>>'{}')::numeric,(f->>'decimal_places')::int) then return false; end if;
   if (v#>>'{}')::numeric<(f->>'min')::numeric or (v#>>'{}')::numeric>(f->>'max')::numeric then return false; end if;
  else
   if jsonb_typeof(v) is distinct from 'string' then return false; end if;
   if f->>'type'='text' and (length(trim(v#>>'{}'))<2 or length(v#>>'{}')>(f->>'maxLength')::int or (v#>>'{}') ~ '[[:cntrl:]]') then return false; end if;
   if f->>'type'='currency' and (v#>>'{}') !~ '^[A-Z]{3}$' then return false; end if;
   if f->>'type'='enum' and not (f->'options' @> jsonb_build_array(v)) then return false; end if;
   if f->>'type'='date' then
    if (v#>>'{}') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return false; end if;
    d:=(v#>>'{}')::date;
    if d<'1950-01-01'::date or d>'2150-12-31'::date or to_char(d,'YYYY-MM-DD')<>v#>>'{}' then return false; end if;
   end if;
  end if;
 end loop;
 if vals->>'valid_from'>vals->>'valid_until' or vals->>'trade_on'>vals->>'settles_on' or vals->>'starts_on'>vals->>'ends_on' or vals->>'trade_on'>vals->>'fixing_on' or vals->>'fixing_on'>vals->>'settles_on' then return false; end if;
 if vals->>'base_currency'=vals->>'quote_currency' then return false; end if;
 if p_terms->>'modality'='ndf' and vals->>'settlement_currency' not in (vals->>'base_currency',vals->>'quote_currency') then return false; end if;
 return true;
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then return false;
end $body$;
revoke all on function public.fin_valid_product_terms(text,jsonb) from public,anon;
grant execute on function public.fin_valid_product_terms(text,jsonb) to authenticated,service_role;
create or replace function public.fin_check_product_terms() returns trigger language plpgsql security invoker set search_path='' as $body$
declare category text; contract_currency text;
begin
 if new.terms ? 'product_terms' then
  select c.product,c.currency into category,contract_currency from public.fin_contracts c where c.id=new.contract_id and c.organization_id=new.organization_id;
  if not public.fin_valid_product_terms(category,new.terms->'product_terms') then raise exception 'invalid contract terms'; end if;
  if new.terms->'product_terms'->'values' ? 'currency' and coalesce(new.terms->>'currency',contract_currency) is distinct from new.terms->'product_terms'->'values'->>'currency' then raise exception 'currency mismatch'; end if;
 end if;
 return new;
end $body$;
revoke all on function public.fin_check_product_terms() from public,anon,authenticated;
drop trigger if exists fin_product_terms_check on public.fin_contract_versions;
create trigger fin_product_terms_check before insert or update on public.fin_contract_versions for each row execute function public.fin_check_product_terms();
${fs.readFileSync('scripts/platform-intelligence/crm-context.sql', 'utf8')}
insert into public.fin_settings(key,value) values ('schema_version', 'financial-platform-intelligence-1') on conflict(key) do update set value=excluded.value,updated_at=now();
notify pgrst,'reload schema';
commit;
`;
const file = 'docs/supabase-financial-platform-intelligence.sql';
if (process.argv.includes('--check')) { if (fs.readFileSync(file, 'utf8') !== sql) throw new Error('Product terms SQL is stale; regenerate.'); }
else fs.writeFileSync(file, sql);
